WITH lines AS (SELECT id, plan, currency, EXPLODE(discounts) AS val FROM price_tiers), remaining_keys AS (SELECT plan, id FROM lines INTERSECT SELECT plan, id FROM price_tiers WHERE plan IN ('pro', 'starter', 'enterprise')), verified AS (SELECT s.* FROM lines s INNER JOIN remaining_keys k ON s.plan = k.plan AND s.id = k.id), base AS (SELECT *, CASE WHEN plan = 'enterprise' THEN 1 ELSE 0 END AS is_enterprise FROM verified WHERE currency NOT IN ('THB', 'EUR')), filtered AS (SELECT *, SUBSTRING(currency, 1, 4) AS currency_prefix, CASE WHEN is_enterprise >= 86 THEN 'High' WHEN is_enterprise >= 40 THEN 'Medium' ELSE 'Low' END AS is_enterprise_band FROM base WHERE currency IN ('THB', 'EUR')) SELECT plan, currency, SUM(val) AS total_val, AVG(is_enterprise) FILTER (WHERE currency = 'EUR') AS eur_avg_is_enterprise, SUM(CASE WHEN plan = 'pro' THEN val ELSE 0 END) AS pro_val, GROUPING(plan) AS grouping_level FROM filtered GROUP BY GROUPING SETS ((plan, currency), (plan), ()) ORDER BY pro_val DESC NULLS LAST
